package com.neu.riketiku.zhishikapian;
import com.neu.riketiku.renzheng.RenZhengYongHu;import jakarta.validation.Valid;import java.util.List;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/teacher") public class KnowledgeCardTeacherController{private final KnowledgeCardService service;public KnowledgeCardTeacherController(KnowledgeCardService service){this.service=service;}@GetMapping("/scopes/{scopeId}/knowledge-cards")public List<KnowledgeCardDtos.Card>list(@AuthenticationPrincipal RenZhengYongHu u,@PathVariable long scopeId){return service.teacherList(u.id(),scopeId);}@PostMapping("/scopes/{scopeId}/knowledge-cards")public KnowledgeCardDtos.Card create(@AuthenticationPrincipal RenZhengYongHu u,@PathVariable long scopeId,@Valid@RequestBody KnowledgeCardDtos.Save r){return service.create(u.id(),scopeId,r);}@PostMapping("/knowledge-cards/{id}/review")public KnowledgeCardDtos.Card review(@AuthenticationPrincipal RenZhengYongHu u,@PathVariable long id,@Valid@RequestBody KnowledgeCardDtos.Review r){return service.review(u.id(),id,r);}@PostMapping(value="/knowledge-cards/{id}/attachments",consumes="multipart/form-data")public KnowledgeCardDtos.Attachment upload(@AuthenticationPrincipal RenZhengYongHu u,@PathVariable long id,@RequestParam("file")org.springframework.web.multipart.MultipartFile file){return service.upload(u.id(),id,file);}@GetMapping("/knowledge-cards/{id}/attachments/{attachmentId}/content")public org.springframework.http.ResponseEntity<byte[]> content(@AuthenticationPrincipal RenZhengYongHu u,@PathVariable long id,@PathVariable long attachmentId){var image=service.content(u.id(),id,attachmentId,true);return org.springframework.http.ResponseEntity.ok().cacheControl(org.springframework.http.CacheControl.noStore()).contentType(org.springframework.http.MediaType.parseMediaType(image.mime())).body(image.bytes());}}
